UPDATE instance_qos_record SET phase = #{update.phase}, switched_at = #{switchedAt},
    replaced_qos_id = #{replacedQosId,jdbcType=VARCHAR},
    failure_message = #{update.failure,jdbcType=LONGVARCHAR},
    updated_at = #{updatedAt}, resource_version = #{version}
WHERE instance_id = #{instanceId} AND operation_id = #{update.operationId}
  AND resource_version < #{version}

UPDATE instance_qos_record SET phase = #{update.phase},
    expiry_parent_max_kbps = #{update.expiryParentPort.maxKbps,jdbcType=INTEGER},
    expiry_parent_max_burst_kbits = #{update.expiryParentPort.maxBurstKbits,jdbcType=INTEGER},
    expiry_sub_max_kbps = #{update.expirySubPort.maxKbps,jdbcType=INTEGER},
    expiry_sub_max_burst_kbits = #{update.expirySubPort.maxBurstKbits,jdbcType=INTEGER},
    failure_message = #{update.failure,jdbcType=LONGVARCHAR},
    expired_at = CASE WHEN #{update.phase} = 'EXPIRED' THEN #{updatedAt} ELSE expired_at END,
    updated_at = #{updatedAt}, resource_version = #{version}
WHERE instance_id = #{instanceId} AND operation_id = #{update.operationId}
  AND resource_version < #{version}

